import * as React from 'react';
import * as S from '@primasoftllc/design-system';
import '@primasoftllc/design-system/styles.css';

var ROWS = [
    { id: 1, name: 'MAZ 5440', plate: 'AB 1234-7', group: 'Грузовики', state: 'moving', speed: 62 },
    { id: 2, name: 'Volvo FH16', plate: 'AC 8871-2', group: 'Грузовики', state: 'parked', speed: 0 },
    { id: 3, name: 'GAZ Next', plate: 'AH 4402-1', group: 'Фургоны', state: 'offline', speed: null },
    { id: 4, name: 'Scania R450', plate: 'AB 3390-6', group: 'Грузовики', state: 'alarm', speed: 91 }
];
var TONE = { moving: 'success', parked: 'neutral', offline: 'danger', alarm: 'warning' }, LABEL = { moving: 'Движение', parked: 'Стоянка', offline: 'Нет связи', alarm: 'Тревога' };
var columns = [{ key: 'name', label: 'Объект', sortable: true, strong: true }, { key: 'plate', label: 'Номер', mono: true },
    { key: 'group', label: 'Группа', sortable: true }, { key: 'state', label: 'Состояние', render: function (r) {
            return <S.DsLozenge tone={TONE[r.state]} dot={true}>
        {LABEL[r.state]}
        </S.DsLozenge>;
        } },
    { key: 'speed', label: 'Скорость, км/ч', mono: true, align: 'right', render: function (r) { return r.speed === null ? '—' : r.speed; } }];
function SortedTable() {
    var sort = React.useState({ key: 'name', dir: 'asc' });
    var rows = ROWS.slice().sort(function (a, b) { return a[sort[0].key].localeCompare(b[sort[0].key], 'ru') * (sort[0].dir === 'asc' ? 1 : -1); });
    return <div className={"demo-stack"}>
    <S.DsTable columns={columns} rows={rows} ariaLabel={'Объекты с сортировкой'} sortKey={sort[0].key} sortDir={sort[0].dir} onSort={function (key, dir) { sort[1]({ key: key, dir: dir }); }}/>
    </div>;
}
function App() {
    return <div className="dstable-example">
    <style>{exampleStyles}</style>
    <SortedTable />
    </div>;
}

const exampleStyles = ".dstable-example{font:var(--ds-type-body);color:var(--ds-fg)}\n.dstable-example .demo-stack{display:flex;flex-direction:column;gap:16px;min-width:0}\n.dstable-example p{margin:0}\n";

export { App as Example };

