    </S.DsButton> : null}
    <S.DsPagination page={page[0]} pageSize={size[0]} pageSizeOptions={[4, 8, 12]} length={ALL_ROWS.length} onPageChange={page[1]} onPageSizeChange={function (next) { size[1](next); page[1](0); }} ariaLabel={'Страницы объектов'}/>
    </div>}/>
    </div>;
}
